interface CodeGenerator {
    String generate();
}

// Approach 1: Counter-based (recommended — zero collisions)
class CounterBasedGenerator implements CodeGenerator {
    private static final String BASE62 = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private final AtomicLong counter;

    public CounterBasedGenerator(long startValue) {
        this.counter = new AtomicLong(startValue);
    }

    @Override
    public String generate() {
        long num = counter.incrementAndGet();
        return toBase62(num);
    }

    private String toBase62(long num) {
        StringBuilder sb = new StringBuilder();
        while (num > 0) {
            sb.insert(0, BASE62.charAt((int)(num % 62)));
            num /= 62;
        }
        // Pad to 7 characters
        while (sb.length() < 7) sb.insert(0, '0');
        return sb.toString();
    }
}

// Approach 2: Hash-based (collision-possible)
class HashBasedGenerator implements CodeGenerator {
    private static final String BASE62 = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private final AtomicLong salt = new AtomicLong();

    @Override
    public String generate() {
        try {
            String input = UUID.randomUUID() + ":" + salt.incrementAndGet();
            byte[] hash = MessageDigest.getInstance("MD5").digest(input.getBytes());
            // Take first 7 base62 chars from hash bytes
            long num = Math.abs(ByteBuffer.wrap(hash).getLong());
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 7; i++) {
                sb.append(BASE62.charAt((int)(num % 62)));
                num /= 62;
            }
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

// Approach 3: Random (collision-possible)
class RandomGenerator implements CodeGenerator {
    private static final String BASE62 = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private final SecureRandom random = new SecureRandom();

    @Override
    public String generate() {
        StringBuilder sb = new StringBuilder(7);
        for (int i = 0; i < 7; i++) {
            sb.append(BASE62.charAt(random.nextInt(62)));
        }
        return sb.toString();
    }
}

class ShortenedUrl {
    private final String shortCode;
    private final String longUrl;
    private final Instant createdAt;
    private final Instant expiresAt;   // null = no expiry
    private final AtomicLong clickCount = new AtomicLong();

    public ShortenedUrl(String shortCode, String longUrl, Duration ttl) {
        this.shortCode = shortCode;
        this.longUrl = longUrl;
        this.createdAt = Instant.now();
        this.expiresAt = (ttl != null) ? createdAt.plus(ttl) : null;
    }

    public boolean isExpired() {
        return expiresAt != null && Instant.now().isAfter(expiresAt);
    }

    public void incrementClicks() { clickCount.incrementAndGet(); }

    public String getShortCode()  { return shortCode; }
    public String getLongUrl()    { return longUrl; }
    public Instant getCreatedAt() { return createdAt; }
    public Instant getExpiresAt() { return expiresAt; }
    public long getClickCount()   { return clickCount.get(); }
}

record UrlStats(String shortCode, String longUrl, long clicks,
                Instant createdAt, Instant expiresAt) {}

class UrlShortenerService {
    private static final int MAX_COLLISION_RETRIES = 5;

    private final ConcurrentHashMap<String, ShortenedUrl> urlMap = new ConcurrentHashMap<>();
    private final CodeGenerator codeGenerator;
    private final String baseUrl;
    private final ScheduledExecutorService cleanupScheduler;

    public UrlShortenerService(CodeGenerator generator, String baseUrl) {
        this.codeGenerator = generator;
        this.baseUrl = baseUrl;
        this.cleanupScheduler = Executors.newSingleThreadScheduledExecutor();
        cleanupScheduler.scheduleAtFixedRate(
            this::cleanupExpired, 1, 1, TimeUnit.HOURS);
    }

    // ── shorten ─────────────────────────
    public String shorten(String longUrl, String customAlias, Duration ttl) {
        validateUrl(longUrl);

        String code;
        if (customAlias != null && !customAlias.isBlank()) {
            // Custom alias path
            validateAlias(customAlias);
            if (urlMap.containsKey(customAlias))
                throw new AliasAlreadyExistsException(customAlias);
            code = customAlias;
        } else {
            // Auto-generate with collision handling
            code = generateUniqueCode();
        }

        ShortenedUrl entry = new ShortenedUrl(code, longUrl, ttl);

        // Atomic put-if-absent for thread safety
        ShortenedUrl existing = urlMap.putIfAbsent(code, entry);
        if (existing != null) {
            // Race condition: another thread beat us with this code
            throw new AliasAlreadyExistsException(code);
        }

        return baseUrl + code;
    }

    // ── redirect (the hot path) ─────────
    public String redirect(String shortCode) {
        ShortenedUrl entry = urlMap.get(shortCode);
        if (entry == null)
            throw new UrlNotFoundException(shortCode);

        // Lazy expiry check
        if (entry.isExpired()) {
            urlMap.remove(shortCode);
            throw new UrlNotFoundException(shortCode + " (expired)");
        }

        // Atomic click increment — no lock needed
        entry.incrementClicks();
        return entry.getLongUrl();
    }

    // ── Stats ───────────────────────────
    public UrlStats getStats(String shortCode) {
        ShortenedUrl entry = urlMap.get(shortCode);
        if (entry == null)
            throw new UrlNotFoundException(shortCode);
        return new UrlStats(entry.getShortCode(), entry.getLongUrl(),
            entry.getClickCount(), entry.getCreatedAt(), entry.getExpiresAt());
    }

    // ── Delete ──────────────────────────
    public void delete(String shortCode) {
        if (urlMap.remove(shortCode) == null)
            throw new UrlNotFoundException(shortCode);
    }

    // ── Code generation with retry ──────
    private String generateUniqueCode() {
        for (int i = 0; i < MAX_COLLISION_RETRIES; i++) {
            String code = codeGenerator.generate();
            if (!urlMap.containsKey(code)) return code;
        }
        throw new RuntimeException(
            "Failed to generate unique code after " + MAX_COLLISION_RETRIES + " attempts");
    }

    // ── Validation ──────────────────────
    private void validateUrl(String url) {
        if (url == null || url.isBlank())
            throw new InvalidUrlException("URL is empty");
        if (!url.startsWith("http://") && !url.startsWith("https://"))
            throw new InvalidUrlException("URL must start with http(s)://");
    }

    private void validateAlias(String alias) {
        if (alias.length() < 3 || alias.length() > 20)
            throw new InvalidAliasException("Alias must be 3-20 characters");
        if (!alias.matches("^[a-zA-Z0-9_-]+$"))
            throw new InvalidAliasException("Alias must be alphanumeric, _, or -");
    }

    // ── Background cleanup ──────────────
    private void cleanupExpired() {
        urlMap.entrySet().removeIf(e -> e.getValue().isExpired());
    }

    public void shutdown() {
        cleanupScheduler.shutdown();
    }
}
